actions.script:
const cf = ec.entity.conditionFactory
hasDuplicates = false
const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
if (party == null || party.privateOwnerUserId) return
const notDuplicates = new Set(Array.from(ec.service.sync().name('mantle.party.DuplicateServices.get#PartyNotDuplicates')
        .parameters({partyId: partyId}).call()?.otherPartyIdList || []))
// the matching parties that are directory parties (not personal contacts), not this one nor one marked not a duplicate
const directoryIds = (ids) => {
    const unique = Array.from(new Set(ids)).filter((id) => id && id !== partyId && !notDuplicates.has(id))
    if (!unique.length) return []
    return Array.from(ec.entity.find('mantle.party.Party').condition(cf.makeCondition('partyId', 'in', unique))
            .condition(cf.makeCondition('privateOwnerUserId', 'equals', null)).selectField('partyId').list()).map((it) => it.partyId)
}

// find matching identifications
// TODO: perhaps filter characters in query somehow? (all non-alphanumeric; dash, dot, comma, space, etc)
const idValues = Array.from(ec.entity.find('mantle.party.PartyIdentification').condition('partyId', partyId)
        .selectField('idValue,partyIdTypeEnumId').list()).map((it) => it.idValue)
if (idValues.length) {
    const dupIdList = ec.entity.find('mantle.party.PartyIdentification').condition(cf.makeCondition('partyId', 'not-equals', partyId))
            .condition(cf.makeCondition('idValue', 'in', idValues)).selectField('partyId,partyIdTypeEnumId,idValue').list()
    if (directoryIds(Array.from(dupIdList).map((it) => it.partyId)).length) { hasDuplicates = true; return }
}

// find matching emails
const emails = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId)
        .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
        .selectField('infoString').list()).map((it) => it.infoString).filter((it) => it)
if (emails.length) {
    const dupEmailList = ec.entity.find('mantle.party.contact.ContactMech').condition('contactMechTypeEnumId', 'CmtEmailAddress')
            .condition(cf.makeCondition('infoString', 'in', emails)).selectField('contactMechId,contactMechTypeEnumId,infoString').list()
    for (const dupEmail of dupEmailList) {
        const dupPcmList = ec.entity.find('mantle.party.contact.PartyContactMech').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
                .condition(cf.makeCondition('partyId', 'not-equals', partyId)).condition('contactMechId', dupEmail.contactMechId).list()
        if (directoryIds(Array.from(dupPcmList).map((it) => it.partyId)).length) { hasDuplicates = true; return }
    }
}

// find matching birthDate and first/last name
const person = ec.entity.find('mantle.party.Person').condition('partyId', partyId).one()
if (person != null && person.birthDate != null) {
    const bdList = ec.entity.find('mantle.party.Person').condition(cf.makeCondition('partyId', 'not-equals', partyId))
            .condition('birthDate', person.birthDate)
            .condition(cf.makeCondition('firstName', 'equals', person.firstName, false, true))
            .condition(cf.makeCondition('lastName', 'equals', person.lastName, false, true)).selectField('partyId').list()
    if (directoryIds(Array.from(bdList).map((it) => it.partyId)).length) { hasDuplicates = true; return }
}

// a similar name (find#PartyNameMatches leaves out personal contacts and the not-duplicate pairs itself)
const nameOut = ec.service.sync().name('mantle.party.DuplicateServices.find#PartyNameMatches').parameters({partyId: partyId, limit: 1}).call()
if (nameOut?.matchList?.length) hasDuplicates = true

iterate.script:
for (const dupTelInfo of (findTelOut.telecomNumberList ?? [])) {
    if (dupTelecomIdsFound.includes(dupTelInfo.contactMechId)) continue
    dupTelecomIdsFound.push(dupTelInfo.contactMechId)
    ;(matchingInfoByPartyId[dupTelInfo.partyId] ??= []).push(Object.assign({}, dupTelInfo, {matchType: 'phone'}))
}

