{partyId:partyId, address1:ppa.address1, unitNumber:ppa.unitNumber, postalCode:ppa.postalCode,
                            postalCodeExt:ppa.postalCodeExt, countryGeoId:ppa.countryGeoId,
                            matchingInfoByPartyId:matchingInfoByPartyId, dupAddressIdsFound:dupAddressIdsFound}

iterate.script:
for (const dupAddrInfo of (findAddrOut.postalAddressList ?? [])) {
    if (dupAddressIdsFound.includes(dupAddrInfo.contactMechId)) continue
    dupAddressIdsFound.push(dupAddrInfo.contactMechId)
    ;(matchingInfoByPartyId[dupAddrInfo.partyId] ??= []).push(Object.assign({}, dupAddrInfo, {matchType: 'address'}))
}

actions.script:
matchList = []
const cf = ec.entity.conditionFactory
let isOrg = false
let names = {}
const excluded = new Set()
if (partyId) {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
    if (party == null || party.privateOwnerUserId) return
    isOrg = party.partyTypeEnumId === 'PtyOrganization'
    names = {firstName: party.firstName, lastName: party.lastName, nickname: party.nickname, organizationName: party.organizationName}
    excluded.add(partyId)
    const notDupOut = ec.service.sync().name('mantle.party.DuplicateServices.get#PartyNotDuplicates').parameters({partyId: partyId}).call()
    for (const otherId of (notDupOut?.otherPartyIdList ?? [])) excluded.add(otherId)
} else {
    isOrg = partyTypeEnumId ? partyTypeEnumId === 'PtyOrganization' : (!!organizationName && !firstName && !lastName)
    names = {firstName: firstName, lastName: lastName, nickname: nickname, organizationName: organizationName}
}
const min = minScore == null ? 85 : Number(minScore)
const max = Math.max(1, Number(limit || 20))

// lower case without accents or punctuation; letters and digits of any script, words split by single spaces
const stripAccents = (text) => typeof text.normalize === 'function' ? text.normalize('NFD').replace(/[̀-ͯ]/g, '') : text
const fold = (text) => stripAccents(String(text ?? '').toLowerCase())
        .replace(/ß/g, 'ss').replace(/æ/g, 'ae').replace(/œ/g, 'oe').replace(/ø/g, 'o').replace(/ł/g, 'l').replace(/đ/g, 'd').replace(/þ/g, 'th')
        .replace(/['’.]/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim()
const suffixes = new Set(['inc', 'incorporated', 'llc', 'llp', 'lp', 'ltd', 'limited', 'gmbh', 'mbh', 'co', 'corp', 'corporation',
    'company', 'plc', 'ag', 'sa', 'sas', 'sarl', 'srl', 'spa', 'bv', 'nv', 'pty', 'pte', 'oy', 'ab', 'kg', 'kk', 'ug', 'lda'])
const orgKey = (name) => {
    const words = fold(name).split(' ').filter((word) => word)
    if (words.length > 1 && words[0] === 'the') words.shift()
    while (words.length > 1 && suffixes.has(words[words.length - 1])) words.pop()
    return words.join(' ')
}
const lastKey = (name) => fold(name).replace(/ /g, '')
const firstKey = (name) => fold(name).split(' ')[0] || ''

const jaroWinkler = (a, b) => {
    if (a === b) return 1
    if (!a || !b) return 0
    const range = Math.max(0, Math.floor(Math.max(a.length, b.length) / 2) - 1)
    const aMatched = new Array(a.length).fill(false)
    const bMatched = new Array(b.length).fill(false)
    let matches = 0
    for (let i = 0; i < a.length; i++) {
        for (let j = Math.max(0, i - range); j < Math.min(b.length, i + range + 1); j++) {
            if (bMatched[j] || a[i] !== b[j]) continue
            aMatched[i] = true; bMatched[j] = true; matches++
            break
        }
    }
    if (!matches) return 0
    let transpositions = 0
    let k = 0
    for (let i = 0; i < a.length; i++) {
        if (!aMatched[i]) continue
        while (!bMatched[k]) k++
        if (a[i] !== b[k]) transpositions++
        k++
    }
    const jaro = (matches / a.length + matches / b.length + (matches - transpositions / 2) / matches) / 3
    let prefix = 0
    while (prefix < 4 && prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) prefix++
    return jaro + prefix * 0.1 * (1 - jaro)
}
const dice = (a, b) => {
    const x = a.replace(/ /g, '')
    const y = b.replace(/ /g, '')
    if (x === y) return 1
    if (x.length < 2 || y.length < 2) return 0
    const grams = new Map()
    for (let i = 0; i < x.length - 1; i++) { const gram = x.substring(i, i + 2); grams.set(gram, (grams.get(gram) || 0) + 1) }
    let shared = 0
    for (let i = 0; i < y.length - 1; i++) {
        const gram = y.substring(i, i + 2)
        const left = grams.get(gram) || 0
        if (left > 0) { shared++; grams.set(gram, left - 1) }
    }
    return 2 * shared / (x.length - 1 + y.length - 1)
}
const firstSimilarity = (a, b) => {
    if (!a || !b) return 0
    if (a === b) return 1
    const [shorter, longer] = a.length <= b.length ? [a, b] : [b, a]
    if (shorter.length === 1) return longer[0] === shorter ? 0.9 : 0
    if (shorter.length >= 3 && longer.startsWith(shorter)) return 0.9
    return jaroWinkler(a, b)
}

// the prefilter: LIKE 'abc%' on the indexed name columns, in the usual capitalizations, with and without accents
const capitalizations = (prefix) => {
    if (!prefix || /[%_]/.test(prefix)) return []
    const lower = prefix.toLowerCase()
    return [prefix, lower, prefix.toUpperCase(), lower.charAt(0).toUpperCase() + lower.substring(1),
        lower.replace(/(^|\s)(\S)/g, (all, space, letter) => space + letter.toUpperCase())]
}
const prefixes = (texts, length) => {
    const found = new Set()
    for (const text of texts) {
        const value = String(text ?? '').trim()
        if (!value) continue
        for (const variant of [value, stripAccents(value)]) for (const prefix of capitalizations(variant.substring(0, length))) found.add(prefix)
    }
    return Array.from(found)
}
const startsWithAny = (field, list) => cf.makeCondition(list.map((prefix) => cf.makeCondition(field, 'like', prefix + '%')), 'or')
const directory = (find) => find.condition(cf.makeCondition('privateOwnerUserId', 'equals', null))
        .condition(cf.makeCondition('disabled', 'not-equals', 'Y', true))

const scored = []
if (isOrg) {
    const key = orgKey(names.organizationName)
    if (key.length < 2) return
    const raw = String(names.organizationName ?? '').trim()
    const withoutThe = raw.replace(/^the\s+/i, '')
    // the name as it starts, without its "The", and with one ("Lund Labs" finds "The Lund Labs")
    const list = prefixes([raw, withoutThe], 3).concat(withoutThe ? prefixes(['The ' + withoutThe], 7) : [])
    if (!list.length) return
    const candidates = directory(ec.entity.find('mantle.party.PartyDetail').condition('partyTypeEnumId', 'PtyOrganization'))
            .condition(startsWithAny('organizationName', Array.from(new Set(list))))
            .selectField('partyId,pseudoId,partyTypeEnumId,organizationName').orderBy('partyId').limit(500).list()
    for (const candidate of candidates) {
        if (excluded.has(candidate.partyId)) continue
        const otherKey = orgKey(candidate.organizationName)
        if (!otherKey) continue
        const score = Math.round(100 * dice(key, otherKey))
        if (score >= min) scored.push({candidate, score})
    }
} else {
    const last = lastKey(names.lastName)
    const firsts = [firstKey(names.firstName), firstKey(names.nickname)].filter((name) => name)
    if (!last || !firsts.length) return
    const lastPrefixes = prefixes([names.lastName], 3)
    const firstPrefixes = prefixes([names.firstName, names.nickname], 1)
    if (!lastPrefixes.length || !firstPrefixes.length) return
    const candidates = directory(ec.entity.find('mantle.party.PartyDetail').condition('partyTypeEnumId', 'PtyPerson'))
            .condition(startsWithAny('lastName', lastPrefixes))
            .condition(cf.makeCondition([startsWithAny('firstName', firstPrefixes), startsWithAny('nickname', firstPrefixes)], 'or'))
            .selectField('partyId,pseudoId,partyTypeEnumId,firstName,lastName,nickname').orderBy('partyId').limit(500).list()
    for (const candidate of candidates) {
        if (excluded.has(candidate.partyId)) continue
        const lastSimilarity = jaroWinkler(last, lastKey(candidate.lastName))
        if (lastSimilarity < 0.9) continue
        const otherFirsts = [firstKey(candidate.firstName), firstKey(candidate.nickname)].filter((name) => name)
        let best = 0
        for (const mine of firsts) for (const theirs of otherFirsts) best = Math.max(best, firstSimilarity(mine, theirs))
        if (best < 0.85) continue
        const score = Math.round(100 * (0.6 * lastSimilarity + 0.4 * best))
        if (score >= min) scored.push({candidate, score})
    }
}
scored.sort((a, b) => b.score - a.score || String(a.candidate.partyId).localeCompare(String(b.candidate.partyId)))
matchList = scored.slice(0, max).map(({candidate, score}) => ({partyId: candidate.partyId, pseudoId: candidate.pseudoId || candidate.partyId,
    partyTypeEnumId: candidate.partyTypeEnumId, name: (ec.resource.expand('PartyNameOnlyTemplate', '', candidate.getMap()) || '').trim(),
    score: score}))

const userId = ec.user.userId || null
if (partyId === otherPartyId) { ec.message.addError('Choose two different parties'); return }
for (const id of [partyId, otherPartyId]) {
    // the party as the user may see it: the entity filters, and a personal contact only its owner's
    const party = ec.entity.find('mantle.party.Party').condition('partyId', id).one()
    if (party == null || (party.privateOwnerUserId && party.privateOwnerUserId !== userId)) { ec.message.addError(`Party ${id} not found`); return }
    if (party.privateOwnerUserId) { ec.message.addError(`Party ${id} is a personal contact, which the duplicate scan leaves out`); return }
    if (party.disabled === 'Y') { ec.message.addError(`Party ${id} is disabled`); return }
}
const [lowId, highId] = partyId < otherPartyId ? [partyId, otherPartyId] : [otherPartyId, partyId]
const now = ec.user.nowTimestamp
const existing = ec.entity.find('mantle.party.PartyNotDuplicate').condition('partyId', lowId).condition('otherPartyId', highId).one()
if (existing != null) {
    existing.set('decidedByUserId', userId)
    existing.set('decidedDate', now)
    if (comments != null) existing.set('comments', comments || null)
    existing.update()
} else {
    ec.service.sync().name('create#mantle.party.PartyNotDuplicate').parameters({partyId: lowId, otherPartyId: highId,
        decidedByUserId: userId, decidedDate: now, comments: comments || null}).call()
    if (ec.message.hasError()) return
}
for (const id of [partyId, otherPartyId]) {
    ec.service.sync().name('mantle.party.DuplicateServices.find#PartyDuplicates').parameters({partyId: id}).call()
    if (ec.message.hasError()) return
}

removed = false
const userId = ec.user.userId || null
const parties = []
for (const id of [partyId, otherPartyId]) {
    const party = ec.entity.find('mantle.party.Party').condition('partyId', id).one()
    if (party == null || (party.privateOwnerUserId && party.privateOwnerUserId !== userId)) { ec.message.addError(`Party ${id} not found`); return }
    parties.push(party)
}
const [lowId, highId] = partyId < otherPartyId ? [partyId, otherPartyId] : [otherPartyId, partyId]
const existing = ec.entity.find('mantle.party.PartyNotDuplicate').condition('partyId', lowId).condition('otherPartyId', highId).one()
if (existing == null) return
existing.delete()
removed = true
for (const party of parties) {
    if (party.disabled === 'Y' || party.privateOwnerUserId) continue
    ec.service.sync().name('mantle.party.DuplicateServices.find#PartyDuplicates').parameters({partyId: party.partyId}).call()
    if (ec.message.hasError()) return
}

// replaces each run of non-letter, non-digit characters becomes one replacement
function replaceNonAlphaNumeric(text, chr) {
    if (text == null || text === '') return text
    return String(text).replace(/[^\p{L}\p{Nd}]+/gu, chr)
}
// Java's String.equalsIgnoreCase: false when either is null
function equalsIgnoreCase(a, b) { return a != null && b != null && String(a).toLowerCase() === String(b).toLowerCase() }
contactNumber = replaceNonAlphaNumeric(contactNumber, '%')
// NOTE: the following is USA phone number specific (3 digit area code, 7 digit number with 3/4 separator)
if (!areaCode && contactNumber.length > 8) {
    areaCode = contactNumber.substring(0,3)
    contactNumber = contactNumber.substring(3)
    if (contactNumber.charAt(0) === '%') contactNumber = contactNumber.substring(1)
}
if (!contactNumber.includes('%') && contactNumber.length > 3) { contactNumber = contactNumber.substring(0,3) + '%' + contactNumber.substring(3) }
fullNumber = (areaCode ? areaCode + '%' : '') + contactNumber

iterate.script:
const dupTelInfo = Object.assign({}, dupTelNum.getMap(), {partyId: dupPcm.partyId})

if (matchingInfoByPartyId != null) (matchingInfoByPartyId[dupPcm.partyId] ??= []).push(dupTelInfo)
if (dupTelecomIdsFound != null) dupTelecomIdsFound.push(dupTelNum.contactMechId)

telecomNumberList.push(dupTelInfo)

actions.script:
// replaces each run of non-letter, non-digit characters becomes one replacement
function replaceNonAlphaNumeric(text, chr) {
    if (text == null || text === '') return text
    return String(text).replace(/[^\p{L}\p{Nd}]+/gu, chr)
}
// Java's String.equalsIgnoreCase: false when either is null
function equalsIgnoreCase(a, b) { return a != null && b != null && String(a).toLowerCase() === String(b).toLowerCase() }
address1 = address1.replaceAll("Road","R%d%").replaceAll("Rd","R%d%").replaceAll("Street","St%").replaceAll("Avenue","Av%").replaceAll("North","N%").replaceAll("South","S%").replaceAll("East","E%").replaceAll("West","W%")
address1 = replaceNonAlphaNumeric(address1, '%') + '%'
unitNumber = unitNumber ? '%' + replaceNonAlphaNumeric(unitNumber, '%') : null

iterate.script:
const dupAddrInfo = Object.assign({}, dupAddress.getMap(), {partyId: dupPcm.partyId})

if (matchingInfoByPartyId != null) (matchingInfoByPartyId[dupPcm.partyId] ??= []).push(dupAddrInfo)
if (dupAddressIdsFound != null) dupAddressIdsFound.push(dupAddress.contactMechId)

postalAddressList.push(dupAddrInfo)

actions.script:
const startTime = Date.now()
const oneDayAgo = startTime - (24 * 60 * 60 * 1000)
const threads = 10
duplicatesFound = 0
partiesChecked = 0
const cf = ec.entity.conditionFactory
// NOTE: no limit on this query, for really big databases this may blow up!
// personal contacts (privateOwnerUserId) are left out of the duplicate scan
const partyList = ec.entity.find("mantle.party.Party")
        .condition(cf.makeCondition("privateOwnerUserId", "equals", null))
        .condition(cf.makeActionConditionDirect("disabled", "equals", null, "N", null, false, false, true, "false"))
        .condition(cf.makeActionConditionDirect("hasDuplicates", "equals", null, "N", null, false, false, true, "false"))
        .condition(cf.makeActionConditionDirect("lastDupCheckDate", "less", String(oneDayAgo), null, null, false, false, true, "false"))
        .selectField("partyId").list()
ec.logger.info(`Found ${partyList.length} parties to check for duplicates`)
// check in batches of parallel async calls; a party whose check fails is logged and the rest are checked
let partyIdList = []
let failed = 0
for (let partyIdx = 0; partyIdx < partyList.length; partyIdx++) {
    partyIdList.push(partyList[partyIdx].partyId)
    if (partyIdList.length === threads || partyIdx === partyList.length - 1) {
        const futureList = []
        for (const checkPartyId of partyIdList) {
            // party may have already been checked since the original query
            const curParty = ec.entity.find("mantle.party.Party").condition("partyId", checkPartyId).one()
            if (curParty == null || curParty.hasDuplicates === "Y") continue
            futureList.push({partyId: checkPartyId, future: ec.service.async().name("mantle.party.DuplicateServices.find#PartyDuplicates")
                    .parameters({partyId:checkPartyId}).callFuture()})
        }
        for (const {partyId: checkedPartyId, future} of futureList) {
            try {
                const dupOut = future.get()
                if (ec.message.hasError()) {
                    ec.logger.error(`Duplicate check of party ${checkedPartyId} failed: ${ec.message.getErrorsString()}`)
                    ec.message.clearErrors()
                    failed++
                    continue
                }
                if (dupOut?.matchingInfoByPartyId && Object.keys(dupOut.matchingInfoByPartyId).length > 0) duplicatesFound = (duplicatesFound + 1)
                partiesChecked = (partiesChecked + 1)
            } catch (t) {
                ec.logger.log("error", `Duplicate check of party ${checkedPartyId} failed`, t)
                failed++
            }
        }
        if (partiesChecked % 100 === 0) ec.logger.log("info", `Progress: checked ${partiesChecked} parties at ${Date.now() - startTime}ms, found ${duplicatesFound} duplicates`, null)
        // clear out list for next set
        partyIdList = []
    }
}
ec.logger.log("info", `Completed. Checked ${partiesChecked} parties in ${Date.now() - startTime}ms, found ${duplicatesFound} duplicates${failed ? `, ${failed} failed` : ''}`, null)

// TODO: the Groovy original disabled entity ECAs for the merge (disableEntityEca and
//     enableEntityEca on the artifact execution facade), the script runtime does not have them so they run here

// Party fields
if (fromParty.externalId && !toParty.externalId) toParty.externalId = fromParty.externalId
if (fromParty.dataSourceId && !toParty.dataSourceId) toParty.dataSourceId = fromParty.dataSourceId
if (fromParty.comments && !toParty.comments) toParty.comments = fromParty.comments
toParty.update()

// copy a value to the to Party if there is not already one with the same primary key (the original EntityValue.refresh())
const copyToParty = (value) => {
    const newVal = value.cloneValue()
    newVal.partyId = toPartyId
    if (ec.entity.find(newVal.getEntityName()).condition(newVal.getPrimaryKeys()).one() == null) newVal.create()
    return newVal
}
// change one field of all records matching another, returns the count (what EntityFind.updateAll did)
const moveAll = (entityName, matchField, changeField) => {
    let count = 0
    for (const value of ec.entity.find(entityName).condition(matchField, fromPartyId).list()) {
        value.set(changeField, toPartyId)
        value.update()
        count++
    }
    return count
}
// merge fields of the from record into the to record where the to record has none
const fillMissing = (toValue, fromValue) => {
    for (const [name, fromFieldValue] of Object.entries(fromValue.getMap())) {
        if (fromFieldValue == null) continue
        if (toValue.get(name) != null) continue
        toValue.set(name, fromFieldValue)
    }
    toValue.update()
}

// Person, Organization fields
const toIsOrg = toParty.partyTypeEnumId === 'PtyOrganization'
const fromIsOrg = fromParty.partyTypeEnumId === 'PtyOrganization'
const toPerson = !toIsOrg ? ec.entity.find("mantle.party.Person").condition("partyId", toPartyId).one() : null
const fromPerson = !fromIsOrg ? ec.entity.find("mantle.party.Person").condition("partyId", fromPartyId).one() : null
let toOrganization = toIsOrg ? ec.entity.find("mantle.party.Organization").condition("partyId", toPartyId).one() : null
const fromOrganization = fromIsOrg ? ec.entity.find("mantle.party.Organization").condition("partyId", fromPartyId).one() : null

if (toIsOrg && toOrganization == null) {
    toOrganization = ec.entity.makeValue("mantle.party.Organization")
    toOrganization.set("partyId", toPartyId)
    toOrganization.create()
}
if (toPerson != null && fromPerson != null) {
    fillMissing(toPerson, fromPerson)
} else if (toOrganization != null && fromOrganization != null) {
    fillMissing(toOrganization, fromOrganization)
} else if (fromPerson != null && toOrganization != null) {
    if (!toOrganization.organizationName) {
        toOrganization.organizationName = `${fromPerson.firstName ?? ''}${fromPerson.middleName ? ' ' + fromPerson.middleName : ''}${fromPerson.lastName ? ' ' + fromPerson.lastName : ''}`
        toOrganization.update()
    }
}

// PartyClassificationAppl
for (const value of ec.entity.find("mantle.party.PartyClassificationAppl").condition("partyId", fromPartyId).list()) {
    // see if to Party already has a PartyClassification of the same type
    const partyClassification = value.classification
    const pcaCount = ec.entity.find("mantle.party.PartyClassificationAndAppl").condition("partyId", toPartyId)
            .condition("classificationTypeEnumId", partyClassification.classificationTypeEnumId)
            .condition(ec.entity.conditionFactory.makeConditionDate("fromDate", "thruDate", null)).count()
    if (pcaCount === 0) copyToParty(value)
}

// PartyContent
contentCount = moveAll("mantle.party.PartyContent", "partyId", "partyId")
if (contentCount) ec.message.addMessage(`Moved ${contentCount} Content records from Party ${fromPartyId} to ${toPartyId}`)

// PartyIdentification
for (const value of ec.entity.find("mantle.party.PartyIdentification").condition("partyId", fromPartyId).list()) copyToParty(value)

// PartyNote
for (const value of ec.entity.find("mantle.party.PartyNote").condition("partyId", fromPartyId).list()) copyToParty(value)

// PartyRelationship
relCount = moveAll("mantle.party.PartyRelationship", "fromPartyId", "fromPartyId")
relCount += moveAll("mantle.party.PartyRelationship", "toPartyId", "toPartyId")
if (relCount) ec.message.addMessage(`Moved ${relCount} Relationships from Party ${fromPartyId} to ${toPartyId}`)

// PartyRole (add all on to party that it doesn't already have)
roleCount = 0
for (const partyRole of ec.entity.find("mantle.party.PartyRole").condition("partyId", fromPartyId).list()) {
    if (ec.entity.find("mantle.party.PartyRole").condition("partyId", toPartyId).condition("roleTypeId", partyRole.roleTypeId).one() == null) {
        ec.service.sync().name("create#mantle.party.PartyRole").parameter("partyId", toPartyId).parameter("roleTypeId", partyRole.roleTypeId).call()
        roleCount++
    }
}

// PartySetting
for (const value of ec.entity.find("mantle.party.PartySetting").condition("partyId", fromPartyId).list()) copyToParty(value)

// UserAccount
moveAll("moqui.security.UserAccount", "partyId", "partyId")

// CommunicationEvent
commCount = moveAll("mantle.party.communication.CommunicationEvent", "fromPartyId", "fromPartyId")
commCount += moveAll("mantle.party.communication.CommunicationEvent", "toPartyId", "toPartyId")
if (commCount) ec.message.addMessage(`Moved ${commCount} Communication Events from Party ${fromPartyId} to ${toPartyId}`)

// PaymentMethod
methodCount = moveAll("mantle.account.method.PaymentMethod", "ownerPartyId", "ownerPartyId")
if (methodCount) ec.message.addMessage(`Moved ${methodCount} Payment Methods from Party ${fromPartyId} to ${toPartyId}`)

// OrderPart
orderCount = moveAll("mantle.order.OrderPart", "vendorPartyId", "vendorPartyId")
orderCount += moveAll("mantle.order.OrderPart", "customerPartyId", "customerPartyId")
for (const opp of ec.entity.find("mantle.order.OrderPartParty").condition("partyId", fromPartyId).list()) {
    copyToParty(opp)
    opp.delete()
}
if (orderCount) ec.message.addMessage(`Moved ${orderCount} Orders from Party ${fromPartyId} to ${toPartyId}`)

// Shipment
shipmentCount = moveAll("mantle.shipment.Shipment", "fromPartyId", "fromPartyId")
shipmentCount += moveAll("mantle.shipment.Shipment", "toPartyId", "toPartyId")
if (shipmentCount) ec.message.addMessage(`Moved ${shipmentCount} Shipments from Party ${fromPartyId} to ${toPartyId}`)

// Invoice
invoiceCount = moveAll("mantle.account.invoice.Invoice", "fromPartyId", "fromPartyId")
invoiceCount += moveAll("mantle.account.invoice.Invoice", "toPartyId", "toPartyId")
for (const inp of ec.entity.find("mantle.account.invoice.InvoiceParty").condition("partyId", fromPartyId).list()) {
    copyToParty(inp)
    inp.delete()
}
if (invoiceCount) ec.message.addMessage(`Moved ${invoiceCount} Invoices from Party ${fromPartyId} to ${toPartyId}`)

// Payment
paymentCount = moveAll("mantle.account.payment.Payment", "fromPartyId", "fromPartyId")
paymentCount += moveAll("mantle.account.payment.Payment", "toPartyId", "toPartyId")
if (paymentCount) ec.message.addMessage(`Moved ${paymentCount} Payments from Party ${fromPartyId} to ${toPartyId}`)

// rows with the party in their primary key: each is copied to the to Party unless it already has the same
// row (a key collision keeps the to Party's), then removed from the from Party; returns the count moved
const cf = ec.entity.conditionFactory
const moveKeyed = (entityName, field, conditions) => {
    let count = 0
    let find = ec.entity.find(entityName).condition(field, fromPartyId)
    for (const [name, value] of Object.entries(conditions || {})) find = find.condition(name, value)
    for (const value of find.list()) {
        const newVal = value.cloneValue()
        newVal.set(field, toPartyId)
        if (ec.entity.find(entityName).condition(newVal.getPrimaryKeys()).one() == null) newVal.create()
        value.delete()
        count++
    }
    return count
}

// WorkEffortParty, RequestParty, CommunicationEventParty, ContactListParty
workCount = moveKeyed("mantle.work.effort.WorkEffortParty", "partyId")
if (workCount) ec.message.addMessage(`Moved ${workCount} Work Effort parties from Party ${fromPartyId} to ${toPartyId}`)
requestCount = moveKeyed("mantle.request.RequestParty", "partyId")
if (requestCount) ec.message.addMessage(`Moved ${requestCount} Request parties from Party ${fromPartyId} to ${toPartyId}`)
commPartyCount = moveKeyed("mantle.party.communication.CommunicationEventParty", "partyId")
if (commPartyCount) ec.message.addMessage(`Moved ${commPartyCount} Communication Event parties from Party ${fromPartyId} to ${toPartyId}`)
listCount = moveKeyed("mantle.marketing.contact.ContactListParty", "partyId")
if (listCount) ec.message.addMessage(`Moved ${listCount} Contact List memberships from Party ${fromPartyId} to ${toPartyId}`)

// PartyConsent (the consent history, kept whole: the merged party's latest rows are as current as the
// to Party's) and the unsubscribe link tokens
consentCount = moveAll("mantle.party.PartyConsent", "partyId", "partyId")
if (consentCount) ec.message.addMessage(`Moved ${consentCount} Consent records from Party ${fromPartyId} to ${toPartyId}`)
moveAll("mantle.marketing.contact.ContactListToken", "partyId", "partyId")

// ContactBookParty: in a book the to Party is already in, its current row stays (a favorite if either was)
// and the from Party's current row is removed; every other row moves
const bookPartyEntity = "mantle.party.contact.ContactBookParty"
const rowKey = (value) => JSON.stringify(value.getPrimaryKeys())
const currentRows = (id) => Array.from(ec.entity.find(bookPartyEntity).condition("partyId", id)
        .condition(cf.makeConditionDate("fromDate", "thruDate", null)).list())
const toCurrentByBook = new Map(currentRows(toPartyId).map((row) => [row.contactBookId, row]))
const fromCurrentKeys = new Set(currentRows(fromPartyId).map(rowKey))
bookCount = 0
for (const row of ec.entity.find(bookPartyEntity).condition("partyId", fromPartyId).list()) {
    const toRow = fromCurrentKeys.has(rowKey(row)) ? toCurrentByBook.get(row.contactBookId) : null
    if (toRow != null) {
        if (row.isFavorite === "Y" && toRow.isFavorite !== "Y") { toRow.set("isFavorite", "Y"); toRow.update() }
    } else {
        const newVal = row.cloneValue()
        newVal.set("partyId", toPartyId)
        if (ec.entity.find(bookPartyEntity).condition(newVal.getPrimaryKeys()).one() == null) newVal.create()
    }
    row.delete()
    bookCount++
}
bookCount += moveKeyed("mantle.party.contact.ContactBookGroupParty", "partyId")
if (bookCount) ec.message.addMessage(`Moved ${bookCount} Contact Book and group memberships from Party ${fromPartyId} to ${toPartyId}`)

// the generic record links and followers of the party record
linkCount = moveKeyed("mantle.party.communication.CommunicationEventRecord", "recordId", {recordEntityName: "mantle.party.Party"})
linkCount += moveKeyed("mantle.work.effort.WorkEffortRecord", "recordId", {recordEntityName: "mantle.party.Party"})
linkCount += moveKeyed("mantle.party.communication.RecordFollower", "recordId", {recordEntityName: "mantle.party.Party"})
if (linkCount) ec.message.addMessage(`Moved ${linkCount} record links and followers from Party ${fromPartyId} to ${toPartyId}`)

// PartyNotDuplicate: the from Party's decisions become the to Party's (the lower id first); one between the two is
// dropped, as they are now one party
for (const row of ec.entity.find("mantle.party.PartyNotDuplicate").condition(cf.makeCondition([
        cf.makeCondition("partyId", "equals", fromPartyId), cf.makeCondition("otherPartyId", "equals", fromPartyId)], "or")).list()) {
    const otherId = row.partyId === fromPartyId ? row.otherPartyId : row.partyId
    if (otherId !== toPartyId) {
        const [lowId, highId] = toPartyId < otherId ? [toPartyId, otherId] : [otherId, toPartyId]
        if (ec.entity.find("mantle.party.PartyNotDuplicate").condition("partyId", lowId).condition("otherPartyId", highId).one() == null) {
            ec.service.sync().name("create#mantle.party.PartyNotDuplicate").parameters({partyId: lowId, otherPartyId: highId,
                decidedByUserId: row.decidedByUserId, decidedDate: row.decidedDate, comments: row.comments}).call()
        }
    }
    row.delete()
}
